-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 28 recettes, 12 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, ph->>'page',
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', coalesce(ph->>'source', 'Wikimedia Commons'), ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · ' || coalesce(ph->>'source', 'Wikimedia Commons'),
        true, true, 'Photo libre vérifiée à l’œil : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"champon-nagasaki","country":"JP","original":"長崎ちゃんぽん (Nagasaki chanpon)","title":"Champon de Nagasaki (nouilles aux fruits de mer et légumes)","en":"Nagasaki champon noodles","es":"Champon de Nagasaki","desc":"Nouilles épaisses servies dans un bouillon laiteux de porc et poulet, garnies de porc, fruits de mer et légumes sautés, nées dans le quartier chinois de Nagasaki.","cat":"Soupe","diff":"medium","prep":25,"cook":20,"serv":4,"place":{"slug":"jp-nagasaki","name":"Nagasaki","type":"city","lat":32.7503,"lng":129.8779,"summary":"Port ouvert sur la Chine et l'Europe, berceau du champon et du castella."},"ing":[["Nouilles champon (ou ramen épaisses)",4,"portions",null],["Poitrine de porc émincée",150,"g",null],["Crevettes et calmars",200,"g",null],["Chou",200,"g",null],["Germes de soja",150,"g",null],["Carotte",1,null,null],["Bouillon de porc et poulet",1.2,"l",null],["Lait",200,"ml",null],["Saindoux ou huile",2,"c. à soupe",null]],"steps":["Faire sauter le porc dans le saindoux à feu vif.","Ajouter les fruits de mer puis le chou, la carotte et les germes de soja.","Verser le bouillon et le lait, porter à frémissement; saler et poivrer.","Ajouter les nouilles directement dans le bouillon et cuire 3 minutes.","Servir dans de grands bols, garniture sur le dessus."],"photo":{"file":"File:Nagasaki champon.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Nagasaki_champon.JPG/1280px-Nagasaki_champon.JPG","page":"https://commons.wikimedia.org/wiki/File:Nagasaki_champon.JPG","author":"Midori","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"Wikimedia Commons"}},{"slug":"okinawa-soba","country":"JP","original":"沖縄そば (Okinawa soba)","title":"Okinawa soba (nouilles de blé, porc braisé sōki)","en":"Okinawa soba","es":"Okinawa soba","desc":"Nouilles de blé épaisses dans un bouillon de porc et de bonite, coiffées de côtes de porc braisées au sucre roux et à l'awamori, spécialité de l'archipel d'Okinawa.","cat":"Soupe","diff":"medium","prep":20,"cook":120,"serv":4,"place":"jp-okinawa","ing":[["Nouilles Okinawa soba",4,"portions",null],["Travers de porc (sōki)",600,"g",null],["Sauce soja",4,"c. à soupe",null],["Sucre roux",3,"c. à soupe",null],["Awamori ou saké",50,"ml",null],["Dashi de bonite",1,"l",null],["Bouillon de porc",500,"ml",null],["Kamaboko",8,"tranches",null],["Gingembre mariné (beni shōga)",4,"c. à soupe",null],["Oignons verts",2,null,null]],"steps":["Blanchir les travers puis les cuire 1 heure dans l'eau; garder le bouillon.","Les braiser 45 minutes avec soja, sucre, awamori et un peu de bouillon.","Mélanger dashi et bouillon de porc, saler légèrement.","Cuire les nouilles et les répartir dans les bols.","Verser le bouillon chaud et garnir de travers, kamaboko, gingembre et oignons verts."],"photo":{"file":"File:JP 沖繩 Okinawa 那霸市 Naha City 國際通 Kokusai-dori shop 沖繩自家製生麵 Yunami Sakashita-ten 板下店 Restaurant food mixed 三枚肉 Pork belly and 排骨麵 rib noodle combo soup bowl February 2026 N13P 03.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/JP_%E6%B2%96%E7%B9%A9_Okinawa_%E9%82%A3%E9%9C%B8%E5%B8%82_Naha_City_%E5%9C%8B%E9%9A%9B%E9%80%9A_Kokusai-dori_shop_%E6%B2%96%E7%B9%A9%E8%87%AA%E5%AE%B6%E8%A3%BD%E7%94%9F%E9%BA%B5_Yunami_Sakashita-ten_%E6%9D%BF%E4%B8%8B%E5%BA%97_Restaurant_food_mixed_%E4%B8%89%E6%9E%9A%E8%82%89_Pork_belly_and_%E6%8E%92%E9%AA%A8%E9%BA%B5_rib_noodle_combo_soup_bowl_February_2026_N13P_03.jpg/1280px-thumbnail.jpg","page":"https://commons.wikimedia.org/wiki/File:JP_%E6%B2%96%E7%B9%A9_Okinawa_%E9%82%A3%E9%9C%B8%E5%B8%82_Naha_City_%E5%9C%8B%E9%9A%9B%E9%80%9A_Kokusai-dori_shop_%E6%B2%96%E7%B9%A9%E8%87%AA%E5%AE%B6%E8%A3%BD%E7%94%9F%E9%BA%B5_Yunami_Sakashita-ten_%E6%9D%BF%E4%B8%8B%E5%BA%97_Restaurant_food_mixed_%E4%B8%89%E6%9E%9A%E8%82%89_Pork_belly_and_%E6%8E%92%E9%AA%A8%E9%BA%B5_rib_noodle_combo_soup_bowl_February_2026_N13P_03.jpg","author":"NORTLAUKAU 26088 JP","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"Wikimedia Commons"}},{"slug":"soup-curry-sapporo","country":"JP","original":"スープカレー (Soup curry)","title":"Soup curry de Sapporo (curry léger et légumes grillés)","en":"Sapporo soup curry","es":"Soup curry de Sapporo","desc":"Bouillon épicé et clair façon curry servi avec une cuisse de poulet mijotée et de gros morceaux de légumes grillés, accompagné de riz à part, création de Sapporo.","cat":"Plat principal","diff":"medium","prep":30,"cook":60,"serv":4,"place":"jp-sapporo","ing":[["Cuisses de poulet",4,null,null],["Bouillon de poulet",1.2,"l",null],["Oignon",1,null,null],["Ail et gingembre",2,"c. à soupe","râpés"],["Poudre de curry",3,"c. à soupe",null],["Garam masala",1,"c. à café",null],["Aubergine, potiron, poivron, pomme de terre",800,"g","en gros morceaux"],["Œufs mollets",4,null,null],["Riz cuit",4,"bols",null]],"steps":["Faire revenir l'oignon, l'ail et le gingembre puis les épices.","Ajouter le poulet et le bouillon; mijoter 45 minutes.","Griller ou frire les légumes en gros morceaux.","Assaisonner le bouillon avec soja et sel.","Servir le bouillon et le poulet dans un bol, légumes et œuf par-dessus, riz à côté."],"photo":{"file":"File:Soupcurry-hareruya.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/2/26/Soupcurry-hareruya.jpg","page":"https://commons.wikimedia.org/wiki/File:Soupcurry-hareruya.jpg","author":"No machine-readable author provided. Oga~commonswiki assumed (based on copyright claims).","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"Wikimedia Commons"}},{"slug":"kushikatsu-osaka","country":"JP","original":"串カツ (Kushikatsu)","title":"Kushikatsu de Shinsekai (brochettes panées et frites)","en":"Osaka kushikatsu","es":"Kushikatsu de Osaka","desc":"Brochettes de viande, de fruits de mer et de légumes panées au panko et frites, trempées une seule fois dans la sauce commune, emblème du quartier Shinsekai d'Osaka.","cat":"Cuisine de rue","diff":"medium","prep":40,"cook":20,"serv":4,"place":"jp-osaka","ing":[["Porc, bœuf ou poulet en cubes",400,"g",null],["Crevettes",8,null,null],["Légumes (oignon, lotus, champignons)",300,"g",null],["Farine",100,"g",null],["Œufs",2,null,null],["Panko",150,"g",null],["Huile de friture",1,"l",null],["Sauce tonkatsu allongée",200,"ml",null],["Chou cru",8,"feuilles",null]],"steps":["Enfiler viandes, crevettes et légumes sur de petites brochettes.","Battre farine, œufs et un peu d'eau en pâte fine.","Tremper les brochettes dans la pâte puis les rouler dans le panko.","Frire à 175 °C 2 à 3 minutes.","Servir avec la sauce commune (un seul trempage!) et des feuilles de chou cru."],"photo":{"file":"File:KushikatsuDaruma01.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/f/f4/KushikatsuDaruma01.jpg","page":"https://commons.wikimedia.org/wiki/File:KushikatsuDaruma01.jpg","author":"Aiko99ann","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"yatsuhashi-kyoto","country":"JP","original":"八ッ橋 (Yatsuhashi)","title":"Nama yatsuhashi de Kyoto (pâte de riz à la cannelle, an)","en":"Kyoto yatsuhashi","es":"Yatsuhashi de Kioto","desc":"Fine pâte de farine de riz parfumée à la cannelle, pliée en triangle autour d'une pâte de haricots rouges, souvenir emblématique de Kyoto.","cat":"Dessert","diff":"medium","prep":30,"cook":15,"serv":16,"place":"jp-kyoto","ing":[["Farine de riz gluant (shiratamako)",100,"g",null],["Farine de riz (jōshinko)",50,"g",null],["Sucre",80,"g",null],["Eau",150,"ml",null],["Cannelle (nikki)",2,"c. à café",null],["Pâte de haricots rouges (anko)",200,"g",null],["Kinako ou fécule",2,"c. à soupe","pour fariner"]],"steps":["Mélanger les farines, le sucre et l'eau en pâte lisse.","Cuire à la vapeur 15 minutes dans un linge humide.","Pétrir la pâte chaude avec la cannelle jusqu'à ce qu'elle soit élastique.","Étaler finement sur un plan fariné de kinako et découper des carrés de 7 cm.","Poser une boule d'anko au centre et plier en triangle."],"photo":{"file":"File:Yatsuhashi 001.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Yatsuhashi_001.jpg/1280px-Yatsuhashi_001.jpg","page":"https://commons.wikimedia.org/wiki/File:Yatsuhashi_001.jpg","author":"Flickr user WordRidden (Jessica Spengler)","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"miso-katsu-nagoya","country":"JP","original":"味噌カツ (Miso katsu)","title":"Miso katsu de Nagoya (porc pané, sauce miso rouge)","en":"Nagoya miso katsu","es":"Miso katsu de Nagoya","desc":"Côtelette de porc panée nappée d'une sauce épaisse au miso rouge hatchō, sucrée et profonde, spécialité de Nagoya servie sur un lit de chou.","cat":"Plat principal","diff":"medium","prep":20,"cook":15,"serv":4,"place":"jp-nagoya","ing":[["Côtelettes de porc désossées",4,null,null],["Farine",50,"g",null],["Œufs",2,null,null],["Panko",150,"g",null],["Miso rouge hatchō",100,"g",null],["Sucre",3,"c. à soupe",null],["Mirin",3,"c. à soupe",null],["Dashi",150,"ml",null],["Chou émincé",300,"g",null],["Sésame",1,"c. à soupe",null]],"steps":["Mijoter miso, sucre, mirin et dashi 5 minutes en sauce épaisse.","Attendrir et saler les côtelettes.","Paner farine, œuf, panko.","Frire à 170 °C 5 à 6 minutes.","Trancher, napper de sauce miso et parsemer de sésame; servir sur le chou."],"photo":{"file":"File:Miso Katsu by jetalone in Nagoya.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/a/af/Miso_Katsu_by_jetalone_in_Nagoya.jpg","page":"https://commons.wikimedia.org/wiki/File:Miso_Katsu_by_jetalone_in_Nagoya.jpg","author":"jetalone from Nagoya","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"shengjianbao-shanghai","country":"CN","original":"生煎包 (Shēngjiān bāo)","title":"Shengjian bao de Shanghai (petits pains juteux poêlés)","en":"Shanghai shengjian bao","es":"Shengjian bao de Shanghái","desc":"Petits pains levés farcis de porc et de gelée de bouillon, poêlés jusqu'à avoir un fond croustillant puis cuits à la vapeur, parsemés de sésame et d'oignon vert.","cat":"Cuisine de rue","diff":"hard","prep":60,"cook":15,"serv":24,"place":"cn-shanghai","ing":[["Farine",300,"g",null],["Levure sèche",4,"g",null],["Eau tiède",160,"ml",null],["Porc haché gras",400,"g",null],["Gelée de bouillon (aspic)",150,"g","coupée en dés"],["Sauce soja et vin de Shaoxing",3,"c. à soupe",null],["Gingembre et oignon vert",2,"c. à soupe",null],["Sésame et oignon vert",2,"c. à soupe","finition"],["Huile",3,"c. à soupe",null]],"steps":["Préparer une pâte levée souple et laisser lever 1 heure.","Mélanger porc, soja, vin, gingembre, oignon vert puis la gelée en dés.","Diviser la pâte en 24 boules, les aplatir et les farcir en plissant.","Les disposer pliure en bas dans une poêle huilée chaude.","Dorer 3 minutes, verser 100 ml d'eau, couvrir et cuire 8 minutes.","Parsemer de sésame et d'oignon vert et servir avec du vinaigre noir."],"photo":{"file":"File:Sheng Jian Bao on a pan.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/6/61/Sheng_Jian_Bao_on_a_pan.jpg","page":"https://commons.wikimedia.org/wiki/File:Sheng_Jian_Bao_on_a_pan.jpg","author":"Brian Harrington Spier","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"cheung-fun-guangzhou","country":"CN","original":"肠粉 (Chángfěn)","title":"Cheung fun de Canton (rouleaux de riz vapeur aux crevettes)","en":"Cantonese cheung fun","es":"Cheung fun cantonés","desc":"Fines feuilles de pâte de riz cuites à la vapeur et roulées autour de crevettes ou de porc, nappées de sauce soja sucrée, incontournables du dim sum cantonais.","cat":"Entrée","diff":"medium","prep":20,"cook":20,"serv":4,"place":"cn-guangdong","ing":[["Farine de riz",120,"g",null],["Fécule de tapioca",20,"g",null],["Amidon de blé",20,"g",null],["Eau",400,"ml",null],["Crevettes décortiquées",250,"g",null],["Huile",1,"c. à soupe",null],["Sauce soja claire",3,"c. à soupe",null],["Sucre",1,"c. à soupe",null],["Oignon vert",2,null,null]],"steps":["Mélanger les farines, l'eau, l'huile et une pincée de sel; laisser reposer 30 minutes.","Huiler un plateau et verser une fine couche de pâte.","Disposer quelques crevettes et cuire 2 minutes à la vapeur vive.","Rouler la feuille à l'aide d'une corne.","Chauffer soja, sucre et un peu d'eau pour la sauce.","Napper les rouleaux et parsemer d'oignon vert."],"photo":{"file":"File:Dim sum dish served in New Jersey restaurant 2.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Dim_sum_dish_served_in_New_Jersey_restaurant_2.JPG/1280px-Dim_sum_dish_served_in_New_Jersey_restaurant_2.JPG","page":"https://commons.wikimedia.org/wiki/File:Dim_sum_dish_served_in_New_Jersey_restaurant_2.JPG","author":"Tomwsulcer","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"Wikimedia Commons"}},{"slug":"chongqing-huoguo","country":"CN","original":"重庆火锅 (Chóngqìng huǒguō)","title":"Fondue chinoise de Chongqing au piment et poivre du Sichuan","en":"Chongqing spicy hot pot","es":"Hot pot de Chongqing","desc":"Bouillon rouge bouillonnant au suif de bœuf, piments séchés et poivre du Sichuan, où chacun cuit tripes, bœuf, tofu et légumes, symbole de la ville-montagne.","cat":"Plat principal","diff":"medium","prep":40,"cook":30,"serv":6,"place":{"slug":"cn-chongqing","name":"Chongqing","type":"city","lat":29.563,"lng":106.5516,"summary":"Mégapole sur le Yangzi, capitale du hot pot épicé."},"ing":[["Suif de bœuf",200,"g",null],["Piments séchés",60,"g",null],["Poivre du Sichuan",3,"c. à soupe",null],["Doubanjiang",4,"c. à soupe",null],["Ail et gingembre",80,"g",null],["Bouillon de bœuf",2,"l",null],["Bœuf finement tranché",500,"g",null],["Tripes et feuillets",300,"g",null],["Tofu, champignons, légumes verts",1,"kg",null],["Huile de sésame et ail (trempette)",150,"ml",null]],"steps":["Faire fondre le suif, y faire revenir ail, gingembre et doubanjiang.","Ajouter piments et poivre du Sichuan et faire frémir 10 minutes à feu doux.","Verser le bouillon et laisser bouillir 20 minutes.","Mettre la marmite au centre de la table sur un réchaud.","Chacun plonge viandes et légumes quelques secondes à quelques minutes.","Tremper dans l'huile de sésame à l'ail avant de manger."],"photo":{"file":"File:Chongqing hotpot 2.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/Chongqing_hotpot_2.jpg/1280px-Chongqing_hotpot_2.jpg","page":"https://commons.wikimedia.org/wiki/File:Chongqing_hotpot_2.jpg","author":"Hawyih","license":"Public domain","licenseUrl":null,"source":"Wikimedia Commons"}},{"slug":"yangrouchuan-xinjiang","country":"CN","original":"羊肉串 (Yángròu chuàn)","title":"Brochettes d'agneau du Xinjiang au cumin","en":"Xinjiang lamb skewers","es":"Brochetas de cordero de Xinjiang","desc":"Petits morceaux d'agneau alternés de gras, grillés sur la braise et saupoudrés de cumin, piment et sel, vendus dans les bazars d'Ürümqi.","cat":"Cuisine de rue","diff":"easy","prep":20,"cook":10,"serv":4,"place":{"slug":"cn-xinjiang","name":"Xinjiang","type":"region","lat":43.8,"lng":87.6,"summary":"Région du nord-ouest chinois, carrefour ouïghour des routes de la soie."},"ing":[["Gigot d'agneau",800,"g",null],["Gras d'agneau",100,"g",null],["Cumin en grains concassé",2,"c. à soupe",null],["Piment en flocons",1,"c. à soupe",null],["Sel",1,"c. à café",null],["Oignon",1,null,"râpé"]],"steps":["Couper l'agneau en petits cubes et le gras en morceaux plus petits.","Mariner avec l'oignon râpé et le sel 30 minutes.","Enfiler sur des brochettes en alternant viande et gras.","Griller sur une braise vive 8 à 10 minutes en retournant.","Saupoudrer généreusement de cumin et de piment pendant la cuisson."],"photo":{"file":"File:Lamb kebabs on tamarisk skewers at Gülhan Restaurant, Beijing (20210402165927).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Lamb_kebabs_on_tamarisk_skewers_at_G%C3%BClhan_Restaurant%2C_Beijing_%2820210402165927%29.jpg/1280px-Lamb_kebabs_on_tamarisk_skewers_at_G%C3%BClhan_Restaurant%2C_Beijing_%2820210402165927%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Lamb_kebabs_on_tamarisk_skewers_at_G%C3%BClhan_Restaurant,_Beijing_(20210402165927).jpg","author":"N509FZ","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"chou-doufu-changsha","country":"CN","original":"臭豆腐 (Chòu dòufu)","title":"Tofu puant noir de Changsha frit, sauce pimentée","en":"Changsha stinky tofu","es":"Tofu apestoso de Changsha","desc":"Tofu fermenté noirci dans une saumure, frit jusqu'à gonfler puis percé et garni de sauce pimentée à l'ail, en-cas nocturne des rues de Changsha.","cat":"Cuisine de rue","diff":"medium","prep":15,"cook":10,"serv":4,"place":{"slug":"cn-changsha","name":"Changsha","type":"city","lat":28.2282,"lng":112.9388,"summary":"Capitale du Hunan, cuisine pimentée et marchés de nuit."},"ing":[["Tofu puant noir (fermenté)",12,"morceaux",null],["Huile de friture",1,"l",null],["Ail",4,"gousses",null],["Piment en flocons",2,"c. à soupe",null],["Sauce soja",2,"c. à soupe",null],["Huile de sésame",1,"c. à café",null],["Coriandre et oignon vert",2,"c. à soupe",null],["Radis mariné",50,"g","facultatif"]],"steps":["Mélanger ail haché, piment, soja, huile de sésame et un peu d'eau en sauce.","Chauffer l'huile à 180 °C.","Frire le tofu 4 à 5 minutes jusqu'à ce qu'il gonfle.","Égoutter et percer chaque morceau au centre.","Remplir de sauce et garnir d'herbes et de radis mariné."],"photo":{"file":"File:Changshachoudoufu.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/c/c2/Changshachoudoufu.jpg","page":"https://commons.wikimedia.org/wiki/File:Changshachoudoufu.jpg","author":"Yinsanhen","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"jianbing-tianjin","country":"CN","original":"煎饼果子 (Jiānbing guǒzi)","title":"Jianbing guozi de Tianjin (crêpe de rue à l'œuf et beignet croustillant)","en":"Tianjin jianbing guozi","es":"Jianbing guozi de Tianjin","desc":"Crêpe de farine de haricot mungo cuite sur une plaque, couverte d'œuf, de sauces, d'oignon vert et de coriandre, repliée autour d'un beignet croustillant, petit-déjeuner de rue de Tianjin.","cat":"Petit-déjeuner","diff":"medium","prep":20,"cook":15,"serv":4,"place":{"slug":"cn-tianjin","name":"Tianjin","type":"city","lat":39.3434,"lng":117.3616,"summary":"Grande ville portuaire près de Pékin, berceau du jianbing guozi."},"ing":[["Farine de haricot mungo",100,"g",null],["Farine de blé",50,"g",null],["Eau",250,"ml",null],["Œufs",4,null,null],["Beignets youtiao ou crackers frits",4,null,null],["Sauce hoisin ou pâte de soja sucrée",4,"c. à soupe",null],["Sauce pimentée",2,"c. à soupe",null],["Oignon vert et coriandre",4,"c. à soupe",null],["Sésame noir",1,"c. à soupe",null]],"steps":["Mélanger les farines et l'eau en pâte fluide.","Étaler une louche de pâte en grande crêpe très fine sur une plaque chaude.","Casser un œuf dessus et l'étaler; parsemer d'oignon vert, coriandre et sésame.","Retourner, badigeonner de sauce sucrée et pimentée.","Poser le beignet au centre et replier la crêpe autour.","Couper en deux et servir aussitôt."],"photo":{"file":"File:Jianbing 1.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/3/3e/Jianbing_1.jpg","page":"https://commons.wikimedia.org/wiki/File:Jianbing_1.jpg","author":"Ernie from beijing, china","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"kathi-roll-kolkata","country":"IN","original":"Kathi roll","title":"Kathi roll de Calcutta (paratha roulé au poulet tikka)","en":"Kolkata kathi roll","es":"Kathi roll de Calcuta","desc":"Paratha feuilletée cuite avec un œuf battu puis roulée autour de brochettes de poulet grillées, oignons, piment et jus de citron, née à Calcutta.","cat":"Cuisine de rue","diff":"medium","prep":30,"cook":20,"serv":4,"place":"in-west-bengal","ing":[["Farine",300,"g",null],["Ghee",4,"c. à soupe",null],["Œufs",4,null,null],["Haut de cuisse de poulet",500,"g",null],["Yaourt",100,"g",null],["Garam masala et piment",2,"c. à café",null],["Oignon rouge",1,null,"émincé"],["Piments verts",2,null,null],["Citron vert",1,null,null]],"steps":["Mariner le poulet en cubes avec yaourt, épices et sel 1 heure.","Pétrir farine, eau, sel et 1 c. à soupe de ghee; reposer 30 minutes.","Griller le poulet en brochettes.","Abaisser des parathas et les cuire au ghee sur une poêle.","Verser un œuf battu sur la paratha, retourner pour le cuire collé à la pâte.","Garnir de poulet, oignon, piment, citron vert, puis rouler dans du papier."],"photo":{"file":"File:Kathiroll.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/2/23/Kathiroll.jpg","page":"https://commons.wikimedia.org/wiki/File:Kathiroll.jpg","author":"kspoddar","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"galouti-kebab-lucknow","country":"IN","original":"Galouti kebab","title":"Galouti kebab de Lucknow (galettes d'agneau fondantes)","en":"Lucknow galouti kebab","es":"Galouti kebab de Lucknow","desc":"Galettes d'agneau haché extrêmement fin, attendri à la papaye crue et parfumé d'une vingtaine d'épices, si fondantes qu'elles se dégustent sans mâcher, héritage des nawabs.","cat":"Entrée","diff":"hard","prep":60,"cook":20,"serv":6,"place":{"slug":"in-lucknow","name":"Lucknow","type":"city","lat":26.8467,"lng":80.9462,"summary":"Capitale de l'Uttar Pradesh, berceau de la cuisine awadhi des nawabs."},"ing":[["Agneau haché très fin",500,"g",null],["Papaye crue râpée",2,"c. à soupe",null],["Oignons frits",50,"g",null],["Farine de pois chiche grillée",2,"c. à soupe",null],["Garam masala awadhi",2,"c. à café",null],["Safran et eau de rose",1,"c. à soupe",null],["Ghee",4,"c. à soupe",null],["Gingembre et ail",1,"c. à soupe",null]],"steps":["Hacher la viande deux fois très finement.","Mélanger avec papaye, oignons frits mixés, gingembre, ail, épices et sel; reposer 4 heures.","Ajouter la farine de pois chiche, le safran et l'eau de rose.","Former de petites galettes fines avec les mains humides.","Les cuire au ghee à feu moyen 2 minutes par face.","Servir avec des parathas sheermal et de l'oignon."],"photo":{"file":"File:Mouth Watering Gauloti Kababs.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2d/Mouth_Watering_Gauloti_Kababs.jpg/1280px-Mouth_Watering_Gauloti_Kababs.jpg","page":"https://commons.wikimedia.org/wiki/File:Mouth_Watering_Gauloti_Kababs.jpg","author":"Fatimahope","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"mysore-pak","country":"IN","original":"Mysore pak","title":"Mysore pak (fondant au ghee et farine de pois chiche)","en":"Mysore pak","es":"Mysore pak","desc":"Confiserie royale du palais de Mysore: farine de pois chiche cuite dans un sirop de sucre et une grande quantité de ghee, poreuse et fondante.","cat":"Dessert","diff":"medium","prep":10,"cook":25,"serv":16,"place":{"slug":"in-mysore","name":"Mysore","type":"city","lat":12.2958,"lng":76.6394,"summary":"Ancienne capitale royale du Karnataka, palais et confiseries."},"ing":[["Farine de pois chiche",150,"g",null],["Sucre",300,"g",null],["Eau",120,"ml",null],["Ghee",300,"g","chaud"]],"steps":["Tamiser la farine de pois chiche et la mélanger à 100 g de ghee.","Cuire sucre et eau jusqu'au sirop à un fil.","Verser le mélange de farine dans le sirop en fouettant.","Ajouter le reste du ghee chaud louche par louche en remuant sans cesse.","Quand la masse mousse et se détache des bords, la verser dans un moule beurré.","Découper en carrés encore tiède."],"photo":{"file":"File:A view of Mysore pa.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/A_view_of_Mysore_pa.jpg/1280px-A_view_of_Mysore_pa.jpg","page":"https://commons.wikimedia.org/wiki/File:A_view_of_Mysore_pa.jpg","author":"Parvathisri","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"khaman-dhokla","country":"IN","original":"Khaman dhokla","title":"Khaman dhokla du Gujarat (gâteau vapeur de pois chiche)","en":"Gujarati khaman dhokla","es":"Khaman dhokla","desc":"Gâteau moelleux et spongieux de farine de pois chiche cuit à la vapeur, arrosé d'un tempérage de moutarde, piment et feuilles de curry, en-cas favori du Gujarat.","cat":"Collation","diff":"easy","prep":15,"cook":20,"serv":6,"place":"in-gujarat","ing":[["Farine de pois chiche",200,"g",null],["Eau",220,"ml",null],["Sucre",1,"c. à soupe",null],["Jus de citron",2,"c. à soupe",null],["Gingembre et piment vert en pâte",1,"c. à soupe",null],["Eno ou bicarbonate",1.5,"c. à café",null],["Graines de moutarde",1,"c. à café",null],["Feuilles de curry",10,null,null],["Coriandre et coco râpée",2,"c. à soupe",null]],"steps":["Mélanger farine, eau, sucre, citron, sel, gingembre et piment.","Ajouter l'Eno, mélanger vivement et verser dans un moule huilé.","Cuire à la vapeur 15 à 20 minutes.","Faire crépiter moutarde, feuilles de curry et piment dans l'huile, ajouter un peu d'eau sucrée.","Verser ce tempérage sur le dhokla découpé en carrés.","Parsemer de coriandre et de coco."],"photo":{"file":"File:Besan Dhokla - Howrah 2015-04-26 8472.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/Besan_Dhokla_-_Howrah_2015-04-26_8472.JPG/1280px-Besan_Dhokla_-_Howrah_2015-04-26_8472.JPG","page":"https://commons.wikimedia.org/wiki/File:Besan_Dhokla_-_Howrah_2015-04-26_8472.JPG","author":"Biswarup Ganguly","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","source":"Wikimedia Commons"}},{"slug":"kuay-teow-reua","country":"TH","original":"ก๋วยเตี๋ยวเรือ (Kuay teow reua)","title":"Kuay teow reua (nouilles des bateaux de Bangkok)","en":"Thai boat noodles","es":"Fideos de barco tailandeses","desc":"Petits bols de nouilles de riz dans un bouillon sombre et épicé au bœuf ou au porc, enrichi de sang et d'épices, vendus jadis depuis des barques sur les canaux.","cat":"Soupe","diff":"medium","prep":30,"cook":120,"serv":4,"place":"th-bangkok","ing":[["Nouilles de riz fines",300,"g",null],["Bœuf (tranches et boulettes)",400,"g",null],["Bouillon de bœuf",1.5,"l",null],["Sauce soja noire et claire",4,"c. à soupe",null],["Anis étoilé, cannelle, coriandre",1,"c. à soupe",null],["Sang de porc (facultatif)",100,"ml",null],["Liseron d'eau et germes de soja",200,"g",null],["Ail frit et couennes frites",4,"c. à soupe",null]],"steps":["Mijoter le bouillon 2 heures avec épices, sauces soja et sucre de palme.","Hors du feu, lier éventuellement avec le sang pour l'épaissir.","Blanchir nouilles et légumes séparément.","Pocher les tranches de bœuf et les boulettes dans le bouillon.","Répartir en petits bols et couvrir de bouillon.","Garnir d'ail frit, de couennes et de piment."],"photo":{"file":"File:Boat Noodles with sliced beef round steak, beef ball, braised shank and tendon.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/Boat_Noodles_with_sliced_beef_round_steak%2C_beef_ball%2C_braised_shank_and_tendon.jpg/1280px-Boat_Noodles_with_sliced_beef_round_steak%2C_beef_ball%2C_braised_shank_and_tendon.jpg","page":"https://commons.wikimedia.org/wiki/File:Boat_Noodles_with_sliced_beef_round_steak,_beef_ball,_braised_shank_and_tendon.jpg","author":"Zheng Zhou","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"sai-ua-chiang-mai","country":"TH","original":"ไส้อั่ว (Sai ua)","title":"Sai ua de Chiang Mai (saucisse aux herbes du Nord)","en":"Chiang Mai sai ua sausage","es":"Sai ua de Chiang Mai","desc":"Saucisse de porc grillée enroulée en spirale, parfumée de citronnelle, galanga, kaffir et pâte de curry rouge, spécialité du Lanna.","cat":"Entrée","diff":"medium","prep":40,"cook":25,"serv":6,"place":"th-chiang-mai-city","ing":[["Porc haché gras",800,"g",null],["Pâte de curry rouge",3,"c. à soupe",null],["Citronnelle",3,"tiges",null],["Galanga",30,"g",null],["Feuilles de kaffir",6,null,null],["Échalotes et ail",80,"g",null],["Sauce poisson",2,"c. à soupe",null],["Boyaux de porc",2,"m",null]],"steps":["Hacher finement citronnelle, galanga, kaffir, échalotes et ail.","Mélanger au porc avec la pâte de curry et la sauce poisson.","Embosser dans les boyaux sans trop serrer et enrouler en spirale.","Piquer et griller à feu doux sur la braise 20 à 25 minutes.","Servir en tranches avec riz gluant, gingembre frais et piments."],"photo":{"file":"File:Thanin market chiang mai sausage.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f7/Thanin_market_chiang_mai_sausage.jpg/1280px-Thanin_market_chiang_mai_sausage.jpg","page":"https://commons.wikimedia.org/wiki/File:Thanin_market_chiang_mai_sausage.jpg","author":"Takeaway","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"moo-ping","country":"TH","original":"หมูปิ้ง (Moo ping)","title":"Moo ping (brochettes de porc grillé au lait de coco)","en":"Thai moo ping","es":"Moo ping tailandés","desc":"Brochettes de porc marinées à la coriandre, l'ail, le sucre de palme et le lait de coco, grillées et servies avec du riz gluant au petit-déjeuner dans les rues de Bangkok.","cat":"Cuisine de rue","diff":"easy","prep":20,"cook":15,"serv":4,"place":"th-bangkok","ing":[["Échine de porc en fines lanières",600,"g",null],["Racines de coriandre, ail, poivre",3,"c. à soupe","pilés"],["Sucre de palme",2,"c. à soupe",null],["Sauce d'huître",2,"c. à soupe",null],["Sauce poisson",1,"c. à soupe",null],["Lait de coco",120,"ml",null],["Riz gluant cuit",4,"portions",null]],"steps":["Piler coriandre, ail et poivre en pâte.","Mélanger avec sucre, sauces et la moitié du lait de coco.","Mariner le porc au moins 3 heures.","Enfiler sur des brochettes de bambou.","Griller sur la braise en badigeonnant de lait de coco.","Servir avec du riz gluant."],"photo":{"file":"File:Mu ping.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/Mu_ping.jpg/1280px-Mu_ping.jpg","page":"https://commons.wikimedia.org/wiki/File:Mu_ping.jpg","author":"Phoebus 28","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"banh-cuon-hanoi","country":"VN","original":"Bánh cuốn","title":"Bánh cuốn de Hanoï (crêpes de riz vapeur au porc)","en":"Hanoi bánh cuốn","es":"Bánh cuốn de Hanói","desc":"Feuilles translucides de pâte de riz cuites à la vapeur et roulées autour de porc haché et de champignons noirs, servies avec chả lụa et nước chấm.","cat":"Petit-déjeuner","diff":"medium","prep":30,"cook":30,"serv":4,"place":"vn-hanoi","ing":[["Farine de riz",200,"g",null],["Fécule de tapioca",30,"g",null],["Eau",500,"ml",null],["Porc haché",250,"g",null],["Champignons noirs",15,"g","réhydratés"],["Échalotes",4,null,null],["Chả lụa (saucisse de porc)",150,"g",null],["Nước chấm",200,"ml",null],["Herbes fraîches",1,"bouquet",null]],"steps":["Mélanger farines, eau et sel; reposer 1 heure.","Faire sauter le porc avec les échalotes et les champignons hachés.","Tendre un linge sur une casserole d'eau bouillante, y étaler une louche de pâte et couvrir 1 minute.","Décoller la feuille, la garnir de farce et la rouler.","Parsemer d'échalotes frites.","Servir avec chả lụa, herbes et nước chấm."],"photo":{"file":"File:Bánh cuốn chả lụa.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/B%C3%A1nh_cu%E1%BB%91n_ch%E1%BA%A3_l%E1%BB%A5a.jpg/1280px-B%C3%A1nh_cu%E1%BB%91n_ch%E1%BA%A3_l%E1%BB%A5a.jpg","page":"https://commons.wikimedia.org/wiki/File:B%C3%A1nh_cu%E1%BB%91n_ch%E1%BA%A3_l%E1%BB%A5a.jpg","author":"stu_spivack","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"banh-beo-hue","country":"VN","original":"Bánh bèo","title":"Bánh bèo de Huế (petits flans de riz aux crevettes)","en":"Huế bánh bèo","es":"Bánh bèo de Hue","desc":"Petites coupelles de pâte de riz vapeur garnies de crevettes séchées pilées, de couennes croustillantes et d'huile d'oignon vert, servies avec de la sauce poisson.","cat":"Entrée","diff":"medium","prep":30,"cook":20,"serv":4,"place":"vn-hue","ing":[["Farine de riz",150,"g",null],["Fécule de tapioca",20,"g",null],["Eau",400,"ml",null],["Crevettes séchées",50,"g",null],["Couennes de porc frites",30,"g",null],["Oignon vert",3,null,null],["Huile",3,"c. à soupe",null],["Nước chấm",100,"ml",null]],"steps":["Mélanger farines, eau et sel; reposer 1 heure.","Huiler de petites coupelles et les chauffer à la vapeur.","Verser une cuillerée de pâte dans chacune et cuire 5 minutes.","Réhydrater et piler les crevettes, les faire sauter.","Verser l'huile chaude sur l'oignon vert haché.","Garnir chaque bánh bèo de crevettes, couennes et huile d'oignon; arroser de nước chấm."],"photo":{"file":"File:Bánh bèo chén.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/0/0d/B%C3%A1nh_b%C3%A8o_ch%C3%A9n.jpg","page":"https://commons.wikimedia.org/wiki/File:B%C3%A1nh_b%C3%A8o_ch%C3%A9n.jpg","author":"Nha Nghi La from Ho Chi Minh, Viet Nam","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"ca-kho-to","country":"VN","original":"Cá kho tộ","title":"Cá kho tộ (poisson caramélisé en pot de terre)","en":"Vietnamese caramelized fish in clay pot","es":"Pescado caramelizado en olla de barro","desc":"Darnes de poisson-chat mijotées dans un caramel sombre, de la sauce poisson et du poivre dans un pot de terre, plat familial du delta du Mékong.","cat":"Plat principal","diff":"easy","prep":15,"cook":40,"serv":4,"place":{"slug":"vn-mekong","name":"Delta du Mékong","type":"region","lat":10.03,"lng":105.78,"summary":"Delta fertile du sud vietnamien, marchés flottants et poissons d'eau douce."},"ing":[["Darnes de poisson-chat",600,"g",null],["Sucre",3,"c. à soupe",null],["Sauce poisson",4,"c. à soupe",null],["Eau de coco",200,"ml",null],["Échalotes et ail",4,"c. à soupe","hachés"],["Poivre noir",1,"c. à café",null],["Piment",1,null,null],["Oignon vert",2,null,null]],"steps":["Mariner le poisson avec sauce poisson, échalotes, ail et poivre 30 minutes.","Faire un caramel brun foncé avec le sucre et un peu d'huile dans le pot.","Y déposer le poisson et le saisir 1 minute de chaque côté.","Ajouter la marinade et l'eau de coco.","Mijoter à découvert 30 minutes jusqu'à une sauce sirupeuse.","Parsemer de poivre, piment et oignon vert; servir avec du riz."],"photo":{"file":"File:Cá kho tộ, cá hú.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/7/7c/C%C3%A1_kho_t%E1%BB%99%2C_c%C3%A1_h%C3%BA.jpg","page":"https://commons.wikimedia.org/wiki/File:C%C3%A1_kho_t%E1%BB%99,_c%C3%A1_h%C3%BA.jpg","author":"Charles Haynes","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"milmyeon-busan","country":"KR","original":"밀면 (Milmyeon)","title":"Milmyeon de Busan (nouilles de blé froides)","en":"Busan milmyeon","es":"Milmyeon de Busan","desc":"Nouilles de blé froides dans un bouillon glacé de bœuf et de porc aigre-doux, avec radis mariné, œuf et moutarde, créées par les réfugiés du Nord à Busan.","cat":"Soupe","diff":"medium","prep":30,"cook":120,"serv":4,"place":"kr-busan","ing":[["Nouilles milmyeon",4,"portions",null],["Jarret de bœuf",400,"g",null],["Os de porc",500,"g",null],["Vinaigre",3,"c. à soupe",null],["Sucre",2,"c. à soupe",null],["Radis mariné",150,"g",null],["Concombre",1,null,null],["Œufs durs",2,null,null],["Moutarde coréenne",2,"c. à café",null]],"steps":["Cuire bœuf et os 2 heures; filtrer et dégraisser le bouillon.","Assaisonner de soja clair, sel, vinaigre et sucre; refroidir jusqu'à presque geler.","Trancher finement le bœuf.","Cuire les nouilles et les rincer à l'eau glacée.","Dresser nouilles, bœuf, radis, concombre et demi-œuf.","Verser le bouillon glacé et servir avec vinaigre et moutarde."],"photo":{"file":"File:Milmyeon choryang yeongdong myeonok.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/Milmyeon_choryang_yeongdong_myeonok.JPG/1280px-Milmyeon_choryang_yeongdong_myeonok.JPG","page":"https://commons.wikimedia.org/wiki/File:Milmyeon_choryang_yeongdong_myeonok.JPG","author":"hyolee2","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"ssiat-hotteok-busan","country":"KR","original":"씨앗호떡 (Ssiat hotteok)","title":"Ssiat hotteok de Busan (crêpes sucrées aux graines)","en":"Busan seed hotteok","es":"Ssiat hotteok de Busan","desc":"Petites galettes levées frites, garnies de sucre brun à la cannelle puis ouvertes et remplies de graines de tournesol et de courge, star du marché de Nampo.","cat":"Cuisine de rue","diff":"medium","prep":20,"cook":15,"serv":8,"place":"kr-busan","ing":[["Farine",300,"g",null],["Farine de riz gluant",50,"g",null],["Lait tiède",250,"ml",null],["Levure sèche",5,"g",null],["Cassonade",100,"g",null],["Cannelle",1,"c. à café",null],["Graines de tournesol, courge et cacahuètes",100,"g",null],["Huile",100,"ml",null]],"steps":["Préparer une pâte collante avec les farines, le lait, la levure, du sucre et du sel; laisser lever 1 heure.","Mélanger cassonade et cannelle.","Huiler les mains, prendre une boule de pâte et y enfermer une cuillerée de sucre.","Frire dans l'huile en aplatissant avec une presse, 2 minutes par face.","Ouvrir la galette sur le côté et la garnir de graines.","Servir chaud dans un gobelet de papier."],"photo":{"file":"File:Hotteok.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/9/97/Hotteok.jpg","page":"https://commons.wikimedia.org/wiki/File:Hotteok.jpg","author":"Korea.net / Korean Culture and Information Service","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"bakso-malang","country":"ID","original":"Bakso Malang","title":"Bakso Malang (soupe de boulettes de bœuf et wontons frits)","en":"Bakso Malang meatball soup","es":"Bakso Malang","desc":"Boulettes de bœuf élastiques dans un bouillon clair, accompagnées de wontons frits, de tofu farci et de nouilles, spécialité de la ville de Malang.","cat":"Soupe","diff":"medium","prep":40,"cook":60,"serv":4,"place":{"slug":"id-malang","name":"Malang","type":"city","lat":-7.9666,"lng":112.6326,"summary":"Ville d'altitude de Java oriental, capitale du bakso."},"ing":[["Bœuf haché maigre",500,"g",null],["Fécule de tapioca",80,"g",null],["Ail",6,"gousses",null],["Blanc d'œuf",1,null,null],["Bouillon d'os de bœuf",1.5,"l",null],["Vermicelles et nouilles jaunes",200,"g",null],["Tofu frit farci",8,"morceaux",null],["Wontons frits",8,null,null],["Céleri, oignons frits, sambal",4,"c. à soupe",null]],"steps":["Mixer le bœuf très froid avec l'ail, le blanc, le sel et la fécule en pâte lisse.","Former des boulettes et les pocher dans l'eau frémissante jusqu'à ce qu'elles flottent.","Les ajouter au bouillon assaisonné.","Répartir nouilles, tofu et wontons dans les bols.","Verser bouillon et boulettes.","Garnir de céleri, oignons frits et sambal."],"photo":{"file":"File:Bakso Daging Sapi.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/2/27/Bakso_Daging_Sapi.jpg","page":"https://commons.wikimedia.org/wiki/File:Bakso_Daging_Sapi.jpg","author":"Christian Losari","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"gado-gado","country":"ID","original":"Gado-gado","title":"Gado-gado de Jakarta (légumes, tofu, sauce cacahuète)","en":"Jakarta gado-gado","es":"Gado-gado de Yakarta","desc":"Salade de légumes blanchis, de tofu, de tempeh, d'œuf et de lontong nappée d'une sauce cacahuète au tamarin, garnie de krupuk, emblème des warungs de Jakarta.","cat":"Plat principal","diff":"easy","prep":30,"cook":20,"serv":4,"place":"id-jakarta","ing":[["Cacahuètes grillées",200,"g",null],["Sucre de palme",30,"g",null],["Tamarin",1,"c. à soupe",null],["Piment et ail",2,"c. à soupe",null],["Chou, haricots verts, germes de soja, épinards",600,"g",null],["Pommes de terre cuites",2,null,null],["Tofu et tempeh frits",200,"g",null],["Œufs durs",2,null,null],["Krupuk",8,null,null]],"steps":["Piler les cacahuètes avec ail, piment, sucre de palme, tamarin et sel; allonger d'eau chaude.","Blanchir séparément chaque légume.","Disposer légumes, pommes de terre, tofu, tempeh et œufs.","Napper de sauce cacahuète.","Garnir d'oignons frits et de krupuk."],"photo":{"file":"File:Gado gado.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Gado_gado.jpg/1280px-Gado_gado.jpg","page":"https://commons.wikimedia.org/wiki/File:Gado_gado.jpg","author":"Sakurai Midori","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"Wikimedia Commons"}},{"slug":"hamsi-tava","country":"TR","original":"Hamsi tava","title":"Hamsi tava de Trabzon (anchois frits à la farine de maïs)","en":"Black Sea hamsi tava","es":"Hamsi tava","desc":"Anchois frais de la mer Noire ouverts, roulés dans la farine de maïs et frits en rosace dans la poêle, servis avec oignon rouge et citron.","cat":"Plat principal","diff":"easy","prep":20,"cook":10,"serv":4,"place":{"slug":"tr-trabzon","name":"Trabzon","type":"city","lat":41.0027,"lng":39.7168,"summary":"Port de la mer Noire, pays de l'anchois (hamsi) et du maïs."},"ing":[["Anchois frais",800,"g",null],["Farine de maïs",120,"g",null],["Huile",150,"ml",null],["Oignon rouge",1,null,null],["Roquette",1,"botte",null],["Citrons",2,null,null]],"steps":["Étêter et vider les anchois, retirer l'arête centrale en les ouvrant.","Saler et les rouler dans la farine de maïs.","Les disposer en cercle serré dans une poêle huilée bien chaude.","Frire 3 minutes, retourner d'un bloc à l'aide d'une assiette et cuire 2 minutes.","Servir avec oignon rouge, roquette et citron."],"photo":{"file":"File:Hamsi tava.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Hamsi_tava.jpg/1280px-Hamsi_tava.jpg","page":"https://commons.wikimedia.org/wiki/File:Hamsi_tava.jpg","author":"E4024","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"simit-istanbul","country":"TR","original":"Simit","title":"Simit d'Istanbul (anneau de pain au sésame et pekmez)","en":"Istanbul simit","es":"Simit de Estambul","desc":"Anneau de pain torsadé trempé dans la mélasse de raisin puis roulé dans le sésame grillé, vendu sur des plateaux et charrettes dans toutes les rues d'Istanbul.","cat":"Pain","diff":"medium","prep":40,"cook":20,"serv":10,"place":"tr-istanbul","ing":[["Farine",500,"g",null],["Eau tiède",300,"ml",null],["Levure sèche",7,"g",null],["Sucre",1,"c. à soupe",null],["Huile",2,"c. à soupe",null],["Pekmez (mélasse de raisin)",4,"c. à soupe",null],["Graines de sésame",200,"g","grillées"]],"steps":["Pétrir farine, eau, levure, sucre, sel et huile; laisser lever 1 heure.","Diviser en 20 boudins; torsader deux boudins ensemble et fermer en anneau.","Tremper dans le pekmez allongé d'eau.","Rouler dans le sésame grillé.","Laisser lever 15 minutes.","Cuire 15 à 20 minutes à 230 °C."],"photo":{"file":"File:Simit vendor next to checkpoint, Nicosia.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/f/fb/Simit_vendor_next_to_checkpoint%2C_Nicosia.jpg","page":"https://commons.wikimedia.org/wiki/File:Simit_vendor_next_to_checkpoint,_Nicosia.jpg","author":"Nicosia Turkish Municipality","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}}]$batch$::jsonb);
